HTML='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Uniformes — PES6 Studio</title>
<style>*{box-sizing:border-box}body{background:#10151f;color:#e5edf7;font:15px system-ui;margin:24px;max-width:1350px}a{color:#8fcbff}select,input,button{padding:9px;margin:4px;background:#24344d;color:white;border:1px solid #587192;border-radius:6px}button{cursor:pointer}button:disabled{opacity:.5}section{padding:16px 0;border-top:1px solid #455670}.parts{display:flex;gap:24px;flex-wrap:wrap}.part{max-width:600px;flex:1;min-width:400px}.images{display:flex;gap:8px}.images img{width:48%;image-rendering:pixelated;background:#293342;border:1px solid #455670}label{display:block}small{color:#acbdd3}#status,#output{white-space:pre-wrap;overflow-wrap:anywhere;min-height:24px}</style>
<nav><a href="/">Galeria</a> · <a href="/clubs">Clubes</a> · <a href="/players">Jogadores</a></nav><h1>Uniformes</h1>
<p>Selecione uma entrada e edite suas duas partes separadamente. Use PNG de <strong>512 × 512</strong>, preservando a disposição das peças no atlas.</p>
<p id="note"></p><p>Referências visuais nas artes originais: <button class="jump" data-entry="5864">Arsenal · 5864</button><button class="jump" data-entry="5865">Arsenal · 5865</button><button class="jump" data-entry="5885">Manchester United · 5885</button><button class="jump" data-entry="6043">Real Madrid · 6043</button><br><small>Identificação visual da arte; uso em partida e função de cada parte ainda exigem teste.</small></p><input id="search" placeholder="Buscar entrada ou vínculo manual"><select id="entry" aria-label="Entrada de uniforme"></select><p id="count"></p><div id="parts" class="parts"></div>
<button id="import">Preparar PNGs selecionados</button><button id="undo">Restaurar as duas partes</button><p><small>O Studio verifica conversão e espaço no arquivo antes de aceitar o conjunto. Texturas iguais em outras entradas permanecem independentes. Uma textura importada não muda modelo 3D, coordenadas UV, cores do uniforme gerado ou referências de equipe.</small></p><p id="status" role="status"></p>
<section><h2>Conferência em jogo</h2><p>Faça uma alteração identificável em uma entrada por vez. Confira o clube, jogador de linha/goleiro e variante usada no jogo. Só depois salve o vínculo manual em cada parte. A escolha do clube aqui organiza o catálogo; ela não redireciona os arquivos carregados pelo jogo.</p></section>
<section><button id="save">Salvar projeto</button><button id="load">Carregar projeto</button><select id="mode"><option value="img">Gerar IMG</option><option value="iso">Gerar ISO</option></select><button id="build">Gerar patch</button><button id="open" hidden>Abrir pasta gerada</button><p id="output" role="status"></p></section>
<script>const $=id=>document.getElementById(id);let data,current=5736,dir;const slots=['Principal','Reserva','Goleiro 1','Goleiro 2','Alternativo','Detalhe'];async function api(url,body){let r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||d.error)throw Error(d.error||r.statusText);return d}async function run(fn){try{await fn()}catch(e){$('status').textContent=e.message}}function filtered(){let q=$('search').value.toLocaleLowerCase(),rows=data.entries.filter(e=>(e.entry+' '+e.parts.map(p=>p.team+' '+p.slot).join(' ')).toLocaleLowerCase().includes(q));$('entry').replaceChildren(...rows.map(e=>new Option('AFS '+e.entry+' · '+e.parts.map(p=>p.team||'sem vínculo').join(' / ')+(e.parts.some(p=>p.modified)?' *':''),e.entry)));if(rows.some(e=>e.entry===current))$('entry').value=current;$('count').textContent=rows.length+' entradas encontradas'}async function refresh(){data=await api('/kits/data');$('note').textContent=data.note;filtered();await show()}async function show(){let value=Number($('entry').value);if(!value){$('parts').replaceChildren();return}current=value;let e=data.entries.find(e=>e.entry===current);$('parts').replaceChildren(...e.parts.map(p=>{let box=document.createElement('div');box.className='part';let h=document.createElement('h2');h.textContent='Parte '+p.part;let names=document.createElement('p');names.textContent='Original / Prévia convertida'+(p.modified?' · alterada':'');let images=document.createElement('div');images.className='images';for(let original of [true,false]){let im=document.createElement('img');im.alt=original?'Textura original':'Textura convertida';im.src='/kits/png?entry='+current+'&part='+p.part+(original?'&original=1':'&v='+Date.now());images.append(im)}let link=document.createElement('a');link.textContent='Baixar PNG original';link.href='/kits/png?entry='+current+'&part='+p.part+'&original=1&download=1';let file=document.createElement('input');file.type='file';file.accept='image/png';file.id='file'+p.part;file.setAttribute('aria-label','PNG da parte '+p.part);let team=document.createElement('input');team.id='team'+p.part;team.value=p.team;team.placeholder='Equipe conferida no jogo';team.maxLength=100;let slot=document.createElement('select');slot.id='slot'+p.part;for(let s of slots)slot.add(new Option(s,s));slot.value=p.slot||'Detalhe';let map=document.createElement('button');map.textContent='Salvar vínculo manual desta parte';map.onclick=()=>run(async()=>{if(hasUploads())throw Error('Prepare os PNGs antes de salvar o vínculo.');await api('/kits/map',{entry:current,part:p.part,team:team.value,slot:slot.value});await refresh();$('status').textContent='Vínculo manual salvo no catálogo.'});let undo=document.createElement('button');undo.textContent='Restaurar parte '+p.part;undo.onclick=()=>run(async()=>{if(!discard())return;await api('/kits/undo',{entry:current,part:p.part});await refresh();$('status').textContent='Parte restaurada.'});box.append(h,names,images,link,document.createElement('br'),file,undo,team,slot,map);return box}))}function hasUploads(){return [0,1].some(p=>$('file'+p)?.files.length)}function discard(){return !hasUploads()||confirm('Descartar PNGs selecionados ainda não preparados?')}$('entry').onchange=()=>run(async()=>{if(!discard()){$('entry').value=current;return}await show()});$('search').onchange=()=>run(async()=>{if(!discard())return;filtered();await show()});function base64(file){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Falha ao ler PNG'));r.readAsDataURL(file)})}$('import').onclick=()=>run(async()=>{try{$('import').disabled=true;let uploads={};for(let p of [0,1]){let f=$('file'+p).files[0];if(f)uploads[p]=await base64(f)}if(!Object.keys(uploads).length)throw Error('Selecione pelo menos um PNG.');$('status').textContent='Convertendo e verificando o conjunto…';await api('/kits/stage',{entry:current,parts:uploads});await refresh();$('status').textContent='Uniforme preparado. Confira as duas prévias antes de salvar e gerar.'}finally{$('import').disabled=false}});$('undo').onclick=()=>run(async()=>{if(!discard())return;await api('/kits/undo',{entry:current});await refresh();$('status').textContent='As duas partes foram restauradas.'});$('save').onclick=()=>run(async()=>{if(hasUploads())throw Error('Prepare os PNGs antes de salvar.');$('status').textContent=(await api('/save',{})).message});$('load').onclick=()=>run(async()=>{if(!confirm('Substituir as alterações atuais pelo projeto salvo?'))return;await api('/load',{});await refresh();$('status').textContent='Projeto carregado.'});$('build').onclick=()=>run(async()=>{if(hasUploads())throw Error('Prepare os PNGs antes de gerar.');try{$('build').disabled=true;$('open').hidden=true;$('output').textContent='Gerando e verificando os arquivos…';let r=await api('/build?mode='+$('mode').value,{});dir=r.output_directory;$('output').textContent='Verificado: '+r.files.join(' | ');$('open').hidden=false}catch(e){$('output').textContent=e.message}finally{$('build').disabled=false}});$('open').onclick=()=>run(async()=>{await api('/openOutput',{directory:dir})});for(let b of document.querySelectorAll('.jump'))b.onclick=()=>run(async()=>{if(!discard())return;$('search').value='';current=Number(b.dataset.entry);filtered();await show()});run(refresh);</script></html>'''
